    private static string Id()=>Guid.NewGuid().ToString("N");
    private static string Command()=>Guid.NewGuid().ToString("D");
    private static string S(JsonNode node,string key)=>node[key]!.GetValue<string>();
    private static async Task<JsonNode> Body(HttpResponseMessage response,HttpStatusCode expected=HttpStatusCode.OK,string? capture=null)
    {
        using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.StatusCode==expected,$"HTTP {(int)response.StatusCode}, expected {(int)expected}: {raw}");if(capture is not null&&Environment.GetEnvironmentVariable("SHOP_PHONE_WIRE_DIR") is{Length:>0} directory){Directory.CreateDirectory(directory);await File.WriteAllTextAsync(Path.Combine(directory,capture+".json"),raw);await File.WriteAllTextAsync(Path.Combine(directory,capture+".meta.json"),JsonSerializer.Serialize(new{method=response.RequestMessage!.Method.Method,path=response.RequestMessage.RequestUri!.PathAndQuery,status=(int)response.StatusCode,actualSqlHttpResponse=true,syntheticQaOnly=true}));}return JsonNode.Parse(raw)!;}
    }
    private async Task<(HttpClient Client,string Owner)> Customer()
    {
        await using var scope=fixture.Sql.Factory.Services.CreateAsyncScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>();var name="phone"+Id();var user=new ShopUser{UserName=name,Email=name+"@example.test",EmailConfirmed=true,DisplayName="Synthetic phone SQL customer"};Assert.True((await users.CreateAsync(user,fixture.Sql.Password)).Succeeded);var auth=await scope.ServiceProvider.GetRequiredService<AuthService>().PasswordAsync(new(name,fixture.Sql.Password),true,true,false,default);var client=fixture.Sql.Factory.CreateClient(new(){HandleCookies=false});client.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3000");client.DefaultRequestHeaders.Authorization=new("Bearer",auth.AccessToken);return(client,user.Id);
    }
    private async Task<(string Listing,string Model,string Name)> Listing(string? term=null)
    {
        var key=Id();var name="Phone "+(term??key);var model=new CatalogModelInput("phones","samsung","qa-phone-"+key,[new("fa","گوشی "+name,"نمونه مصنوعی SQL"),new("en",name,"Synthetic phone SQL")],[new("battery",TextFa:"باتری نمونه",TextEn:"Sample battery")],["/products/phone-green.svg"],null);var result=await Body(await fixture.Writer.PostAsJsonAsync("/api/admin/market/models",new CreateMarketModelInput(model,new("Published","qa-phone",key,"منبع خصوصی","PRIVATE SOURCE",null,"unknown",null,null,null,true))));var listing=S(result,"id");var detail=await Body(await fixture.Writer.GetAsync("/api/admin/market/"+listing));return(listing,S(detail,"modelId"),name);
    }
    private static PhoneConfigurationInput Choice(int ram=8,int storage=256,string color="black",bool enabled=true,string? variant=null)=>new(enabled,ram,storage,color,color=="black"?"مشکی":"سفید",color=="black"?"Black":"White",color=="black"?"#000000":"#ffffff","/products/phone-green.svg",variant);
    private async Task<(string Id,JsonNode Result)> Config(string listing,PhoneConfigurationInput? choice=null)
    {
        var id=Id();var current=await Body(await fixture.Writer.GetAsync($"/api/admin/market/{listing}/phone-configurations"));var result=await Body(await fixture.Writer.PutAsJsonAsync($"/api/admin/market/{listing}/phone-configurations/{id}/commands/{Command()}",new PhoneConfigurationCommand(S(current,"listingVersion"),null,choice??Choice())));return(id,result);
    }
    private async Task<string> Variant(string model,int ram=8,int storage=256,string color="black")
    {
        await using var scope=fixture.Sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<CatalogDbContext>();var product=await db.Products.Include(p=>p.PurchaseMethods).SingleAsync(p=>p.Id==model);product.Status="Published";if(!product.PurchaseMethods.Any(p=>p.MethodId=="online"))product.PurchaseMethods.Add(new(){ProductId=model,MethodId="online"});var definitions=await db.AttributeDefinitions.Include(d=>d.Options).Where(d=>d.Key=="ram"||d.Key=="storage").ToArrayAsync();var id=Id();var variant=new ProductVariant{Id=id,ProductId=model,Sku="QA-PHONE-"+id,PriceRial=123,LabelFa="نمونه SQL",LabelEn="Synthetic SQL",Color=color=="black"?"#000000":"#ffffff",ColorNameFa=color=="black"?"مشکی":"سفید",ColorNameEn=color=="black"?"Black":"White",WarrantyFa="گارانتی مصنوعی SQL",WarrantyEn="Synthetic SQL warranty"};foreach(var definition in definitions){var value=definition.Key=="ram"?ram:storage;var option=Id();if(definition.Key=="storage"&&storage==1024){var existingTb=definition.Options.SingleOrDefault(value=>value.LabelEn=="1 TB");Assert.NotNull(existingTb);variant.Attributes.Add(new(){AttributeId=definition.Id,ValueOptionId=existingTb.Id});}else if(definition.DataType!=AttributeDataType.Number){definition.Options.Add(new(){Id=option,Value="qa-"+option,LabelFa=value+" گیگابایت",LabelEn=value+" GB"});variant.Attributes.Add(new(){AttributeId=definition.Id,ValueOptionId=option});}else variant.Attributes.Add(new(){AttributeId=definition.Id,ValueNumber=value});}Assert.Equal(2,variant.Attributes.Count);db.Variants.Add(variant);await db.SaveChangesAsync();return id;
    }
    private static async Task<JsonNode> Select(HttpClient client,string listing,string configuration)
    {
        var before=await Body(await client.GetAsync("/api/cart/en/sourcing"));return await Body(await client.PutAsJsonAsync("/api/cart/en/sourcing",new CartSourcingInput([new CartSourcingLineInput(listing,1){ConfigurationId=configuration}],before["version"]?.GetValue<string>())));
    }

    [Fact]public async Task PublicProjectionAndFacetsUseAllModelsAndConfigurationAxesWithoutSourceOrPrice()
    {
        var term=Id();var one=await Listing(term);var two=await Listing(term);await Config(one.Listing);await Config(one.Listing,Choice(12,512,"white"));await Config(two.Listing,Choice(8,128));
        var page=await Body(await fixture.Writer.PostAsJsonAsync("/api/phones/en/search",new PhoneSearchInput(Query:term,PageSize:1)),capture:"discovery-page");Assert.Single(page["items"]!.AsArray());Assert.Contains(page["items"]![0]!["specifications"]!.AsArray(),value=>S(value!,"key")=="battery"&&S(value!,"label")=="Battery"&&S(value!,"value")=="Sample battery");Assert.Equal(2,page["total"]!.GetValue<int>());Assert.Equal(2,page["facets"]!["ramGb"]![0]!["count"]!.GetValue<int>());Assert.Equal(2,page["facets"]!["ramGb"]!.AsArray().Count);Assert.Equal(2,page["facets"]!["brands"]![0]!["count"]!.GetValue<int>());
        var filtered=await Body(await fixture.Writer.PostAsJsonAsync("/api/phones/en/search",new PhoneSearchInput(Query:term,RamGb:12,PageSize:1)));Assert.Equal(1,filtered["total"]!.GetValue<int>());Assert.Equal(2,filtered["facets"]!["ramGb"]!.AsArray().Count);Assert.All(page["items"]![0]!["configurations"]!.AsArray(),c=>{Assert.True(c!["canRequest"]!.GetValue<bool>());Assert.True(c["canNotify"]!.GetValue<bool>());Assert.Null(c["variantId"]);});
        foreach(var field in new[]{"source","referencePriceRial","priceRial","sourceUrl","observedAt","validUntil","sourceNameEn"})Assert.DoesNotContain('"'+field+'"',page.ToJsonString(),StringComparison.OrdinalIgnoreCase);
    }
    [Fact]public async Task ConfigurationCommandsReplayBeforeVersionsAndRejectIdentityMutationAndUnauthorizedWrites()
    {
        var phone=await Listing();var id=Id();var current=await Body(await fixture.Writer.GetAsync($"/api/admin/market/{phone.Listing}/phone-configurations"));var command=Command();var input=new PhoneConfigurationCommand(S(current,"listingVersion"),null,Choice());var route=$"/api/admin/market/{phone.Listing}/phone-configurations/{id}/commands/{command}";var saved=await Body(await fixture.Writer.PutAsJsonAsync(route,input),capture:"configuration-save");Assert.True((await Body(await fixture.Writer.PutAsJsonAsync(route,input)))["replayed"]!.GetValue<bool>());Assert.True((await Body(await fixture.Writer.GetAsync("/api/admin/market/phone-configuration-commands/"+command)))["replayed"]!.GetValue<bool>());
        using(var conflict=await fixture.Writer.PutAsJsonAsync(route,input with{Configuration=Choice(12)}))Assert.Equal(HttpStatusCode.Conflict,conflict.StatusCode);
        var update=input with{ListingVersion=S(saved,"listingVersion"),ConfigurationVersion=S(saved,"configurationVersion"),Configuration=Choice(12)};using(var conflict=await fixture.Writer.PutAsJsonAsync(route.Replace(command,Command()),update))Assert.Equal(HttpStatusCode.Conflict,conflict.StatusCode);
        using(var denied=await fixture.Content.PutAsJsonAsync(route,input))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);
    }
    [Fact]public async Task InterestCommandsAreOwnerScopedHistoricalAndIndependentFromCartOrFinancialState()
    {
        var phone=await Listing();var config=await Config(phone.Listing);var person=await Customer();using var client=person.Client;var command=Command();var route=$"/api/phones/interests/{phone.Listing}/commands/{command}";var input=new PhoneInterestInput(config.Id,true);var result=await Body(await client.PutAsJsonAsync(route,input),capture:"interest-created");Assert.False(result["canPay"]!.GetValue<bool>());Assert.Equal(phone.Name,S(result["interest"]!,"modelNameEn"));Assert.Equal("Active",S(result["interest"]!,"state"));Assert.True((await Body(await client.PutAsJsonAsync(route,input)))["replayed"]!.GetValue<bool>());Assert.Single((await Body(await client.GetAsync("/api/phones/interests"),capture:"interest-page"))["items"]!.AsArray());Assert.Empty((await Body(await client.GetAsync("/api/cart/en/sourcing")))["lines"]!.AsArray());
        await Body(await client.GetAsync($"/api/phones/interests/{phone.Listing}/{config.Id}"),capture:"interest-current");var other=await Customer();using var foreign=other.Client;using(var absent=await foreign.GetAsync($"/api/phones/interests/{phone.Listing}/{config.Id}"))Assert.Equal(HttpStatusCode.NotFound,absent.StatusCode);using(var absent=await foreign.GetAsync("/api/phones/interests/commands/"+command))Assert.Equal(HttpStatusCode.NotFound,absent.StatusCode);
        var cancelled=await Body(await client.PutAsJsonAsync($"/api/phones/interests/{phone.Listing}/commands/{Command()}",new PhoneInterestInput(config.Id,false,S(result["interest"]!,"version"))));Assert.Equal("Cancelled",S(cancelled["interest"]!,"state"));var receipt=await Body(await client.GetAsync("/api/phones/interests/commands/"+command),capture:"interest-receipt");Assert.Equal("Active",S(receipt["interest"]!,"state"));var active=await Body(await client.PutAsJsonAsync($"/api/phones/interests/{phone.Listing}/commands/{Command()}",new PhoneInterestInput(config.Id,true,S(cancelled["interest"]!,"version"))));Assert.Equal(2,active["interest"]!["generation"]!.GetValue<int>());
        await using var scope=fixture.Sql.Factory.Services.CreateAsyncScope();Assert.Equal(1,await scope.ServiceProvider.GetRequiredService<MarketDbContext>().PhoneInterests.CountAsync(i=>i.OwnerId==person.Owner));Assert.False(await scope.ServiceProvider.GetRequiredService<SalesDbContext>().Orders.AnyAsync(o=>o.OwnerId==person.Owner));
    }
    [Fact]public async Task ConfiguredCartUpdatesSameRowAndSubmittedRequestKeepsImmutableConfiguration()
    {
        var phone=await Listing();var one=await Config(phone.Listing);var two=await Config(phone.Listing,Choice(12,512,"white"));await using(var sourceScope=fixture.Sql.Factory.Services.CreateAsyncScope()){var sourceDb=sourceScope.ServiceProvider.GetRequiredService<MarketDbContext>();var source=await sourceDb.Listings.SingleAsync(l=>l.Id==phone.Listing);source.SourceUrl="https://private-source.example.test/item";source.ReferencePriceRial=9007199254740993;source.Availability="available";source.ObservedAt=DateTimeOffset.UtcNow.AddHours(-1);source.ValidUntil=DateTimeOffset.UtcNow.AddHours(1);await sourceDb.SaveChangesAsync();}var person=await Customer();using var client=person.Client;await Select(client,phone.Listing,one.Id);await Select(client,phone.Listing,two.Id);var cart=await Body(await client.GetAsync("/api/cart/en/sourcing"),capture:"configured-cart");Assert.Single(cart["lines"]!.AsArray());Assert.Equal(two.Id,S(cart["lines"]![0]!,"configurationId"));var candidate=cart["lines"]![0]!["candidate"]!;Assert.Equal(two.Id,S(candidate["configuration"]!,"id"));Assert.Equal("Phone sourcing request",S(candidate,"sourceNameEn"));Assert.Null(candidate["referencePriceRial"]);Assert.Null(candidate["sourceUrl"]);Assert.Equal("unknown",S(candidate,"availability"));var expected=candidate["configuration"]!.ToJsonString();var result=await Body(await client.PostAsJsonAsync("/api/cart/en/sourcing/submit",new SourcingSubmitInput(Command(),S(cart,"version"),[new(phone.Listing,S(candidate,"fingerprint"))])),HttpStatusCode.Created,capture:"configured-submit");var request=S(result,"id");var detail=await Body(await client.GetAsync("/api/sourcing/requests/"+request),capture:"configured-request");Assert.Equal(expected,detail["lines"]![0]!["configuration"]!.ToJsonString());Assert.Equal("Phone sourcing request",S(detail["lines"]![0]!,"sourceNameEn"));Assert.Null(detail["lines"]![0]!["referencePriceRial"]);using(var staff=await fixture.ReuseStaff("SalesManager")){var admin=await Body(await staff.GetAsync("/api/admin/sourcing/requests/"+request));Assert.Equal("PRIVATE SOURCE",S(admin["lines"]![0]!,"sourceNameEn"));Assert.Equal("9007199254740993",S(admin["lines"]![0]!,"referencePriceRial"));}
        await using(var scope=fixture.Sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<MarketDbContext>();var config=await db.PhoneConfigurations.SingleAsync(c=>c.Id==two.Id);config.Enabled=false;config.ColorNameEn="Changed label";await db.SaveChangesAsync();}
        Assert.Equal(expected,(await Body(await client.GetAsync("/api/sourcing/requests/"+request)))["lines"]![0]!["configuration"]!.ToJsonString());Assert.Empty((await Body(await client.GetAsync("/api/cart/en/sourcing")))["lines"]!.AsArray());
    }
    [Theory][InlineData(256)][InlineData(1024)]public async Task ActualStockOnlyEnablesExactConfigurationAndNotifiesOncePerExplicitGeneration(int storage)
    {
        var phone=await Listing();var variant=await Variant(phone.Model,8,storage);var config=await Config(phone.Listing,Choice(storage:storage,variant:variant));var otherConfig=await Config(phone.Listing,Choice(12,512,"white"));var person=await Customer();using var client=person.Client;var interest=await Body(await client.PutAsJsonAsync($"/api/phones/interests/{phone.Listing}/commands/{Command()}",new PhoneInterestInput(config.Id,true)));
        async Task<int> Notify(){await using var scope=fixture.Sql.Factory.Services.CreateAsyncScope();return await scope.ServiceProvider.GetRequiredService<PhoneDiscoveryCoordinator>().NotifyOwnerAsync(person.Owner,default);}
        Assert.Equal(0,await Notify());await using(var scope=fixture.Sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<InventoryDbContext>();db.Stock.Add(new(){VariantId=variant,OnHand=1});await db.SaveChangesAsync();}
        var detail=await Body(await client.GetAsync("/api/phones/en/"+phone.Listing),capture:"exact-stock-detail");var choices=detail["configurations"]!.AsArray();Assert.True(choices.Single(c=>S(c!,"id")==config.Id)!["availableInStore"]!.GetValue<bool>());Assert.False(choices.Single(c=>S(c!,"id")==otherConfig.Id)!["availableInStore"]!.GetValue<bool>());Assert.True(choices.Single(c=>S(c!,"id")==otherConfig.Id)!["canRequest"]!.GetValue<bool>());Assert.Equal(1,await Notify());Assert.Equal(0,await Notify());Assert.Equal("Notified",S(await Body(await client.GetAsync($"/api/phones/interests/{phone.Listing}/{config.Id}")),"state"));
        var inbox=await Body(await client.GetAsync("/api/notifications/phones"),capture:"availability-inbox");Assert.Single(inbox["items"]!.AsArray());Assert.Equal("phone_available",S(inbox["items"]![0]!,"kind"));Assert.Equal("Active",S((await Body(await client.GetAsync("/api/phones/interests/commands/"+S(interest,"requestId"))))["interest"]!,"state"));
    }
