    [Fact]public async Task SelectedConfigurationUsesExistingQuoteConsentReceivingAllocationAndPurchaseWithoutFakePayment()
    {
        var phone=await Listing();var originallyLinked=await Variant(phone.Model);var config=await Config(phone.Listing,Choice(variant:originallyLinked));var person=await Customer();using var customer=person.Client;var cart=await Select(customer,phone.Listing,config.Id);var candidate=cart["lines"]![0]!["candidate"]!;var submitted=await Body(await customer.PostAsJsonAsync("/api/cart/en/sourcing/submit",new SourcingSubmitInput(Command(),S(cart,"version"),[new(phone.Listing,S(candidate,"fingerprint"))])),HttpStatusCode.Created);var request=S(submitted,"id");var good=await Variant(phone.Model);var wrong=await Variant(phone.Model,12,512);using var finance=await fixture.ReuseStaff("FinanceManager");using var sales=await fixture.ReuseStaff("SalesManager");using var inventory=await fixture.ReuseStaff("InventoryManager");var offer=Id();var line=Id();var adminOffer=$"/api/admin/sourcing/requests/{request}/offers/{offer}";var publicOffer=$"/api/sourcing/requests/{request}/offers/{offer}";
        async Task<SourcingOfferSaveInput> OfferInput(string variant){var parent=await Body(await finance.GetAsync($"/api/admin/sourcing/requests/{request}"));var sku=await Body(await finance.GetAsync($"/api/admin/sourcing/requests/{request}/offer-skus/{variant}?listingId={phone.Listing}"));var now=DateTimeOffset.UtcNow;return new(Command(),S(parent["summary"]!,"version"),null,[new(line,phone.Listing,variant,1,"9007199254740993",S(sku,"materialFingerprint"),S(sku,"currentFingerprint"))],"فقط رضایت تأمین مصنوعی SQL","Synthetic SQL procurement consent only",now.AddMinutes(20),now.AddHours(2));}
        using(var mismatch=await finance.PutAsJsonAsync(adminOffer,await OfferInput(wrong)))Assert.Equal(HttpStatusCode.Conflict,mismatch.StatusCode);
        await Body(await finance.PutAsJsonAsync(adminOffer,await OfferInput(good)),capture:"flow-admin-quote");var draft=await Body(await finance.GetAsync(adminOffer));var summary=draft["offer"]!["summary"]!;var publish=new SourcingOfferPublishInput(Command(),S(draft,"requestVersion"),S(summary,"version"),S(summary,"termsHash"));await Body(await finance.PostAsJsonAsync(adminOffer+"/publish",publish),capture:"flow-published");await Body(await finance.PostAsJsonAsync(adminOffer+"/publish",publish));var inbox=await Body(await customer.GetAsync("/api/notifications/phones"),capture:"flow-quote-inbox");Assert.Single(inbox["items"]!.AsArray());Assert.Equal("sourcing_offer_published",S(inbox["items"]![0]!,"kind"));Assert.Equal(request,S(inbox["items"]![0]!,"requestId"));
        var published=await Body(await customer.GetAsync(publicOffer),capture:"flow-customer-quote");Assert.False(published["canPay"]!.GetValue<bool>());summary=published["offer"]!["summary"]!;await Body(await customer.PostAsJsonAsync(publicOffer+"/accept",new SourcingOfferActionInput(Command(),S(published,"requestVersion"),S(summary,"version"),S(summary,"termsHash"))),capture:"flow-consent");var accepted=await Body(await customer.GetAsync(publicOffer));summary=accepted["offer"]!["summary"]!;var task=Id();await Body(await sales.PutAsJsonAsync(adminOffer+"/supply/"+task,new SourcingSupplyStartInput(Command(),S(accepted,"requestVersion"),S(summary,"version"),S(summary,"termsHash"))),capture:"flow-supply");
        var mappingId=Id();await Body(await inventory.PutAsJsonAsync("/api/admin/inventory/receiving-unit-mappings/"+mappingId,new ReceivingUnitMappingInput(Id(),"PhoneQA-"+Id(),"001","Main","each",good,1,1,"عدد نمونه","Synthetic each",true,null)));var mapping=JsonSerializer.Deserialize<ReceivingUnitMappingData>((await Body(await inventory.GetAsync("/api/admin/inventory/receiving-unit-mappings/"+mappingId))).ToJsonString(),new JsonSerializerOptions(JsonSerializerDefaults.Web))!;var view=await Body(await inventory.GetAsync("/api/admin/inventory/sourcing-tasks/"+task));var receiveTask=view["task"]!;var receivingInput=new SourcingReceiptInput(Id(),S(receiveTask,"requestVersion"),S(receiveTask["task"]!,"version"),"manual",mapping.OriginSystem,mapping.CompanyKey,mapping.WarehouseKey,"PHONE-QA-"+Id(),DateTimeOffset.UtcNow.AddMinutes(-1),"Synthetic physical SQL receipt",false,[new(line,"001",mapping.Id,mapping.Version,"1",S(view["stock"]![0]!,"trackingMode"),view["stock"]![0]!["version"]?.GetValue<string>(),[])]);SourcingReceivingRules.Normalize(receivingInput);var received=await Body(await inventory.PostAsJsonAsync($"/api/admin/inventory/sourcing-requests/{request}/tasks/{task}/receipts/{Id()}",receivingInput),capture:"flow-received");Assert.Single(received["lines"]!.AsArray());
        var allocation=await Body(await inventory.GetAsync("/api/admin/inventory/sourcing-tasks/"+task+"/allocation"));var stock=allocation["stock"]![0]!;await Body(await inventory.PutAsJsonAsync($"/api/admin/inventory/sourcing-requests/{request}/tasks/{task}/allocations/{Id()}",new SourcingAllocationInput(Id(),S(allocation,"requestVersion"),S(allocation,"taskVersion"),S(allocation,"offerVersion"),S(allocation,"acceptanceId"),S(allocation,"termsHash"),DateTimeOffset.UtcNow.AddMinutes(10),"Synthetic actual stock allocation",[new(line,S(stock,"version"),S(stock,"trackingMode"),[])])),capture:"flow-allocated");
        var purchase=await Body(await customer.GetAsync(publicOffer+"/purchase"),capture:"flow-purchase");Assert.True(purchase["canConvert"]!.GetValue<bool>());Assert.False(purchase["canPay"]!.GetValue<bool>());var convert=new SourcingConversionInput(Command(),S(purchase,"taskId"),S(purchase,"requestVersion"),S(purchase,"taskVersion"),S(purchase,"offerVersion"),S(purchase,"acceptanceId"),S(purchase["agreement"]!,"id"),S(purchase["agreement"]!,"version"),S(purchase["allocation"]!,"allocationId"),S(purchase["allocation"]!,"version"),S(purchase,"termsHash"),purchase["cartVersion"]?.GetValue<string>());await Body(await customer.PostAsJsonAsync(publicOffer+"/convert",convert),capture:"flow-converted");var finalCart=await Body(await customer.GetAsync("/api/cart/en/v2"),capture:"flow-negotiated-cart");Assert.Single(finalCart["offerLines"]!.AsArray());Assert.Equal("9007199254740993",S(finalCart["offerLines"]![0]!,"unitPriceRial"));
        await using var scope=fixture.Sql.Factory.Services.CreateAsyncScope();var inv=scope.ServiceProvider.GetRequiredService<InventoryDbContext>();var balance=await inv.Stock.SingleAsync(s=>s.VariantId==good);Assert.Equal(1,balance.OnHand);Assert.Equal(1,balance.SourcingReserved);Assert.Equal(0,balance.Reserved);Assert.Single(await inv.Movements.Where(m=>m.VariantId==good).ToArrayAsync());Assert.False(await scope.ServiceProvider.GetRequiredService<SalesDbContext>().Orders.AnyAsync(o=>o.OwnerId==person.Owner));
    }
    [Fact]public async Task DowngradeCannotDiscardPhoneConfigurationOrInterestHistory()
    {
        var phone=await Listing();await Config(phone.Listing);await using var scope=fixture.Sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<MarketDbContext>();var prior=db.Database.GetMigrations().TakeWhile(m=>!m.EndsWith("_PhoneDiscovery",StringComparison.Ordinal)).Last();var failure=await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.GetService<IMigrator>().MigrateAsync(prior));Assert.Equal(51000,failure.Number);Assert.True(await db.PhoneConfigurations.AnyAsync(c=>c.ListingId==phone.Listing));
    }
}
